import subprocess, numpy as np, wave, json, os
def call(name,args):
    p=subprocess.run(['ft2','call',name,json.dumps(args)],capture_output=True,text=True)
    return p.stdout.strip()
def render(path):
    call('module_render',{'path':path,'rate':44100,'bits':16})
    w=wave.open(path); d=np.frombuffer(w.readframes(w.getnframes()),'<i2').astype(float)/32768
    return d
def rms_rows(d, n=40, rowdur=2.5/150, sr=44100):
    out=[]
    for r in range(n):
        a=int(r*rowdur*sr); seg=d[a:a+int(rowdur*sr)]
        if len(seg)<100: break
        out.append(round(float(np.sqrt((seg**2).mean())),4))
    return out
for row in [0,1,2,3,4,5,8]:
    call('pattern_clear',{'pattern':0})
    call('pattern_set_cell',{'pattern':0,'row':row,'channel':0,'note':73,'instrument':1,'volume':64})
    d=render('/workspace/probe.wav')
    print('row',row,rms_rows(d)[:24])
EOF
python3 probe.py"}

